from work import *
c,h=witnesses(19);t=c
for a,b in {r'\unsure{L|\mathscr{L}}':r'\mathcal L',r'\unsure{biordonné|bien donné}':'biordonné',r'\unsure{;|,}':',',r'\unsure{\mathrm{Pstrf}|\mathrm{Ps\,tr\,f}}':r'\mathrm{Pstrf}',r'\unsure{formé}':'formé',r'T_i^{\unsure{\cdot|\prime}}':r'T_i^{\cdot}',r'\unsure{\mathrm{Disp}|\mathrm{Dsp}}':r'\mathrm{Drap}',r'B_{\unsure{0|o}}':r'\unsure{B|S}_{0}',r'\unsure{relative|relation}':'relative',r'\unsure{a|x}':'a',r'\{x,y\}\in\mathrm{Disp}_2':r'\{a,y\}\in\mathrm{Drap}_2',r'\unsure{\subset|\in}':r'\subset'}.items():t=t.replace(a,b)
# The looped ground-set L differs from the angular L in the later X=L line.
t=t.replace(r'X\subset L',r'X\subset\mathcal L').replace(r'\mathrm{Pstrf}(L)',r'\mathrm{Pstrf}(\mathcal L)').replace(r'fermés de $L$',r'fermés de $\mathcal L$').replace(r'_2(L)',r'_2(\mathcal L)').replace(r'_{0}(L)',r'_{0}(\mathcal L)')
t=t.replace(r'X=\bigcup T_i'+'\n\\]',r'X=\bigcup T_i'+'\n\\]\n'+r'\margin{\unsure{un|en} disj.}')
t=t.replace(r'par \unsure{$X$ et $Y$} (',r'par \unsure{$Y$} (').replace(r'\unsure{donc} \unsure{sont|sont en}',r'\unsure{donc} $X$ et $Y$ \unsure{sont|sont en}')
t+='\n% pale vertical watermark\n'+r'\rotatebox{90}{\textsc{\unsure{ng Extra Strong}}}'+'\n'
R=[row('theorem opening',r'L/scr L; biordonné/bien donné; semicolon/comma; Pstrf/Ps tr f; cancelled formé uncertain',r'cal L; binordonné; ens.; clean X; cancelled unread',r'cal L; biordonné, ens; Pstrf; cancelled formé de; overwritten U/X retained','The initial L has the long lower loop used for the calligraphic ground set. Biordonné has one connecting n-group, not binordonné; the punctuation after it is a comma. The abbreviation ens has no terminal point. Formé de remains readable beneath the horizontal cancellation.','019_top.jpg','misread word','high'),row('condition a cancellation and wording',r'old ∂ signs uncertain; T_i dot/prime; cancelled est; (ou encore; on a',r'old signs unread; est live; comme; on a unread',r'old ∂ signs remain uncertain; first T_i dot resolved; cancelled est; (ou encore; on a','The first high mark is a round ink dot comparable to the mark on the following T_j. Est is crossed through. Ou ends the previous line and encore begins the next; the baseline on a is faint but legible. The four old boundary-sign fragments remain uncertain.','019_condition.jpg','deletion state','high',marked=True),row('pair notation',r'Disp/Dsp_2 and B_0/o(L)',r'Drap_2 and frak S_0(cal L), with B_0 noted as possible',r'Drap_2(cal L) and unsure B/S_0(cal L)','The lower abbreviation has a descending p after ra; it reads Drap rather than Disp. The zero is a small closed oval. The upper initial has two loop-like lobes with a leftward return, so B versus S remains a genuine glyph uncertainty rather than a mathematical substitution.','019_condition.jpg','misread symbol or index','medium'),row('oblique annotation to b','omitted','omitted',r'\margin{\unsure{un|en} disj.}','A short oblique note is physically present just to the right of T_i. After rotation its final group reads disj. with a dotted i and terminal point; the first two joined letters remain un/en. It is not a union index.','019_union_full.jpg','omission','medium'),row('unique family and NB',r'I est d’unique/unique [=/dot les T_i ... de U]; NB U=∅ sss I=∅',r'I est unique [les T_i ... de X]; NB X=∅ ssi I=∅',r'C’s U, sss and marked unique/bracket uncertainties retained','The component clause ends with an untouched U, not the crossed-and-replaced X used in the formulas. The small NB likewise begins U and has three s-shaped strokes. The extra stroke before unique and small mark after the bracket remain doubtful.','019_unique.jpg / 019_top.jpg','misread symbol or index','high',C=False),row('boundary formulas and naming',r'old ∂U/∂X and U/X revisions; sss; open parenthesis; (partie modérée) fermée',r'clean X; ssi; closed parenthesis; partie modérée fermée without parenthesis',r'C’s revision layers, sss, unclosed parenthesis and parenthesis before fermée retained','The old U forms are overlaid by X, with a separate blackened boundary expression before the second formula. Three s strokes stand between the empty-boundary and full/empty alternatives. No closing parenthesis appears at the right edge of the consequence; in the naming sentence the visible closing parenthesis precedes fermée.','019_unique.jpg / 019_definition.jpg','deletion state','medium',C=False),row('definition wording',r'Def; relative/relation; X^dot et Y^dot le sont; no si',r'Déf; inserted si and union; unread predicate',r'Def; relative; X^dot et Y^dot le sont; no supplied si','Relative is fully written. Between the two boundary variables stands the ordinary et stroke, not a union sign; le sont follows. The manuscript has no visible si before this phrase. The heading has no clearly separate acute accent.','019_definition.jpg','text not on the page','high'),row('last quantified condition',r'a/x≠y and {x,y}∈Disp_2',r'x≠y and {x,y}∈Drap_2',r'a≠y and {a,y}∈Drap_2','The small a in the inequality has a closed bowl and a rightward exit, unlike the crossed x at the quantifier. The same bowl-shaped a appears in the displayed pair. Drap ends in a p-descender and has a subscript 2. These are literal variable switches, not silently corrected formulas.','019_last_formula.jpg','misread symbol or index','high'),row('marginal example',r'modérées/modérés; subset/in; par unsure X et Y; i.e./lire; p.r. à; donc; sont/sont en',r'whole note unread',r'modérées/modérés retained; subset resolved; uncertain Y after par; X et Y placed in final clause; other crowded words uncertain','Rotation separates the ordinary X⊂Y from the retraced X^dot⊂Y, whose two arms form an inclusion sign. The visible X et Y belongs to the final lower line, after the parenthetic p.r. à Y^dot phrase. Several short words overlap the main definition and remain explicitly uncertain rather than being completed from the expected argument.','019_margin_full.jpg / 019_margin_90.jpg','readable ink left as \\ill{}','medium',marked=True),row('SA21-K3-06','comp. conn. de U','comp. conn. de X','comp. conn. de U','The written claim is retained. S proposes a mathematical refinement concerning maximal pseudo-tronçons and ordinary connected components; its cited later scan 030 is outside the supplied page images. This does not authorize changing the present words.','019_unique.jpg','other','high',C=False,H=False),row('watermark','omitted','omitted',r'\unsure{ng Extra Strong}','Pale outline letters are interrupted by the handwriting. The visible fragment is recorded at low confidence without extending it into an unprinted full brand name.','019_watermark.jpg','omission','low')]
R[7]['consequential']='The final condition literally changes from quantified x to a in both a≠y and {a,y}; the transcription does not repair this.'
